sys_script_include.script:
// Name: LeaveFlowAjax     Client callable: TRUE     Accessible from: This application scope only
var LeaveFlowAjax = Class.create();
LeaveFlowAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getHolidays: function() {
        var year = this.getParameter('sysparm_year');
        var country = gs.getProperty('x_2236918_leavef_1.holiday_country', 'BR');
        var result = new HolidayService().getHolidays(year, country);
        return JSON.stringify(result);
    },
    type: 'LeaveFlowAjax'
});
